/**
 * Nano Icons — app icon set.
 *
 * Usage:
 * ```tsx
 * import { Icon } from "@components/common/Icon";
 *
 * <Icon name="heart" size={24} color="tomato" />
 * ```
 *
 * How to add new icons:
 * 1. Drop your .svg files into `assets/icons/app-icons/`
 * 2. Run `expo prebuild` (or `npx react-native-nano-icons --path .nanoicons.json`)
 * 3. The glyphmap is auto-generated at `assets/icons/nanoicons/app-icons.glyphmap.json`
 * 4. Import names are derived from SVG file names (e.g. heart.svg → name="heart")
 *
 * NOTE: Uncomment the lines below after adding at least one SVG and running prebuild.
 *
 * @see https://github.com/software-mansion-labs/react-native-nano-icons
 */

